CREATE TABLE inventory_part_details(plant_id TEXT NOT NULL,workspace TEXT NOT NULL,part_id TEXT NOT NULL,content TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,updated_by TEXT NOT NULL REFERENCES users(id),updated_at TEXT NOT NULL,PRIMARY KEY(plant_id,workspace,part_id),FOREIGN KEY(plant_id,workspace,part_id) REFERENCES inventory_parts(plant_id,workspace,part_id));
CREATE TABLE inventory_catalog_events(id TEXT PRIMARY KEY,plant_id TEXT NOT NULL,workspace TEXT NOT NULL,part_id TEXT NOT NULL,actor_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,reason TEXT NOT NULL,snapshot TEXT NOT NULL,FOREIGN KEY(plant_id,workspace,part_id) REFERENCES inventory_parts(plant_id,workspace,part_id));
